import pytest
from jinja2 import Environment
from jinja2 import DictLoader
from jinja2.ext import i18n


class TestI18nBlockPGettext:
    def test_block_pgettext(self):
        env = Environment(
            loader=DictLoader(
                {
                    "main": """
                        {% pgettext "my_context" %}Hello{% endpgettext %}
                        {% pgettext "another_context" %}World{% endpgettext %}
                    """
                }
            ),
            extensions=[i18n],
        )

        # Mock the gettext functions to observe calls
        calls = []

        def mock_pgettext(context, message):
            calls.append(("pgettext", context, message))
            return f"[{context}]{message}"

        env.install_gettext_callables(lambda x: x, lambda s, p, n: s, mock_pgettext, lambda c, s, p, n: s)

        template = env.get_template("main")
        result = template.render()

        assert result.strip() == "[my_context]Hello\n[another_context]World"
        assert calls == [
            ("pgettext", "my_context", "Hello"),
            ("pgettext", "another_context", "World"),
        ]

    def test_block_pgettext_with_variables(self):
        env = Environment(
            loader=DictLoader(
                {
                    "main": """
                        {% pgettext "greeting" name="John" %}Hello, %(name)s!{% endpgettext %}
                    """
                }
            ),
            extensions=[i18n],
        )

        calls = []

        def mock_pgettext(context, message):
            calls.append(("pgettext", context, message))
            return f"[{context}]{message}"

        env.install_gettext_callables(lambda x: x, lambda s, p, n: s, mock_pgettext, lambda c, s, p, n: s)

        template = env.get_template("main")
        result = template.render()

        assert result.strip() == "[greeting]Hello, John!"
        assert calls == [
            ("pgettext", "greeting", "Hello, %(name)s!"),
        ]

    def test_block_pgettext_with_pluralize(self):
        env = Environment(
            loader=DictLoader(
                {
                    "main": """
                        {% pgettext "item_count" num=1 %}One item{% pluralize %}{{ num }} items{% endpgettext %}
                        {% pgettext "item_count" num=5 %}One item{% pluralize %}{{ num }} items{% endpgettext %}
                    """
                }
            ),
            extensions=[i18n],
        )

        calls = []

        def mock_npgettext(context, singular, plural, n):
            calls.append(("npgettext", context, singular, plural, n))
            if n == 1:
                return f"[{context}]{singular}"
            return f"[{context}]{plural}"

        env.install_gettext_callables(lambda x: x, lambda s, p, n: s, lambda c, m: m, mock_npgettext)

        template = env.get_template("main")
        result = template.render()

        expected = "[item_count]One item\n[item_count]5 items"
        assert result.strip() == expected
        assert calls == [
            ("npgettext", "item_count", "One item", "%(num)s items", 1),
            ("npgettext", "item_count", "One item", "%(num)s items", 5),
        ]

